CREATE TABLE recovery_conversations(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),step INTEGER NOT NULL CHECK(step BETWEEN 1 AND 6),fatigue INTEGER CHECK(fatigue BETWEEN 1 AND 5),sleep_quality INTEGER CHECK(sleep_quality BETWEEN 1 AND 5),motivation INTEGER CHECK(motivation BETWEEN 1 AND 5),soreness_hours REAL,worsening_joint_pain INTEGER CHECK(worsening_joint_pain IN(0,1)),status TEXT NOT NULL CHECK(status IN('pending','completed','cancelled','expired')),expires_at TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,completed_at TEXT);
CREATE INDEX idx_recovery_conversations_pending ON recovery_conversations(user_id,status,expires_at);
